+              <strong>Clear responses</strong>
+              <span>Share the essentials once and avoid back-and-forth on basic details.</span>
+            </div>
+            <div class="highlight-card">
+              <strong>Fast routing</strong>
+              <span>Your request goes straight to the product support queue with contact information attached.</span>
+            </div>
+          </div>
+        </section>
+      `;
+    }
+
+    function SupportPage() {
+      return `
+        <main class="page-shell">
