    .form-panel {
      border: 1px solid var(--surface-border);
      border-radius: var(--radius-xl);
      background: var(--surface);
      backdrop-filter: blur(18px);
      box-shadow: var(--shadow);
    }

    .hero-panel {
      padding: 40px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: 28px;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 14px;
      border-radius: 999px;
      background: rgba(37, 99, 235, 0.1);
      color: var(--primary-dark);
      font-size: 0.92rem;
      font-weight: 700;
    }

    h1 {
      margin: 0 0 16px;
      font-size: clamp(2rem, 4vw, 3.25rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .hero-copy {
      margin: 0;
      max-width: 32rem;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.65;
    }

    .highlights {
      display: grid;
      gap: 14px;
    }

    .highlight-card {
      padding: 16px 18px;
      border-radius: var(--radius-lg);
      background: rgba(255, 255, 255, 0.74);
      border: 1px solid rgba(148, 163, 184, 0.18);
    }

    .highlight-card strong {
      display: block;
      margin-bottom: 6px;
      font-size: 0.96rem;
    }

    .highlight-card span {
      color: var(--muted);
      font-size: 0.94rem;
      line-height: 1.5;
    }

    .form-panel {
      padding: 32px;
    }

    .panel-heading {
      margin-bottom: 24px;
    }

    .panel-heading h2 {
      margin: 0 0 10px;
      font-size: 1.55rem;
      letter-spacing: -0.03em;
    }

    .panel-heading p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    .form-field label {
      font-weight: 700;
      font-size: 0.96rem;
    }

    .field-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      flex-wrap: wrap;
    }

    .required-badge {
      color: var(--primary-dark);
      font-size: 0.84rem;
      font-weight: 700;
    }

    input {
      width: 100%;
      border: 1px solid rgba(148, 163, 184, 0.38);
      border-radius: var(--radius-md);
      background: #fff;
      color: var(--text);
      padding: 14px 16px;
      font: inherit;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #94a3b8;
    }

    input:focus {
      outline: none;
      border-color: rgba(37, 99, 235, 0.7);
      box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.14);
      transform: translateY(-1px);
    }

    input[aria-invalid="true"] {
      border-color: var(--danger);
      box-shadow: 0 0 0 4px rgba(220, 38, 38, 0.1);
    }

    .helper-text {
      margin: 0;
      color: var(--muted);
      font-size: 0.88rem;
      line-height: 1.5;
    }

    .error-text {
      min-height: 1.25rem;
      margin: 0;
      color: var(--danger);
      font-size: 0.88rem;
      font-weight: 600;
    }

    .submit-row {
      display: grid;
      gap: 12px;
      margin-top: 4px;
    }

    .submit-button {
      border: 0;
      border-radius: 16px;
      padding: 15px 18px;
      font: inherit;
      font-weight: 800;
      color: #fff;
      background: linear-gradient(135deg, var(--primary), #0ea5e9);
      cursor: pointer;
      transition: transform 0.18s ease, box-shadow 0.18s ease, opacity 0.18s ease;
      box-shadow: 0 18px 30px rgba(37, 99, 235, 0.28);
    }

    .submit-button:hover {
      transform: translateY(-1px);
      box-shadow: 0 22px 34px rgba(37, 99, 235, 0.3);
    }

    .submit-button:focus-visible {
      outline: 3px solid rgba(37, 99, 235, 0.25);
      outline-offset: 3px;
    }

    .status-message {
      min-height: 1.4rem;
      margin: 0;
      font-size: 0.92rem;
      font-weight: 700;
    }

    .status-message.success {
      color: var(--success);
    }

    .status-message.error {
      color: var(--danger);
    }

    @media (max-width: 900px) {
      .page-shell {
        grid-template-columns: 1fr;
      }

      .hero-panel,
      .form-panel {
        padding: 28px;
      }
    }

    @media (max-width: 560px) {
      body {
        padding: 16px;
      }

      .hero-panel,
      .form-panel {
        padding: 22px;
        border-radius: 24px;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>
  <script>
    const fieldState = {
      fullName: "",
      email: "",
      phone: ""
    };

    const fieldErrors = {
      fullName: "",
      email: "",
      phone: ""
    };

    let formStatus = "";
    let formStatusType = "";

    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const phonePattern = /^\+?[0-9\s().-]{7,20}$/;

    function escapeHtml(value) {
      return value
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
    }

    function validateField(name, value) {
      const trimmedValue = value.trim();

      if (name === "fullName") {
        if (!trimmedValue) {
          return "Full name is required.";
        }

        if (trimmedValue.length < 2) {
          return "Enter your full name.";
        }
      }

      if (name === "email") {
        if (!trimmedValue) {
          return "Email address is required.";
        }

        if (!emailPattern.test(trimmedValue)) {
          return "Enter a valid email address.";
        }
      }

      if (name === "phone" && trimmedValue && !phonePattern.test(trimmedValue)) {
        return "Use a valid phone number format.";
      }

      return "";
    }

    function validateForm() {
      let isValid = true;

      Object.keys(fieldState).forEach((fieldName) => {
        const error = validateField(fieldName, fieldState[fieldName]);
        fieldErrors[fieldName] = error;
        if (error) {
          isValid = false;
        }
      });

      return isValid;
    }

    function Field({
      id,
      label,
      type,
      placeholder,
      value,
      required,
      helperText,
      errorText
    }) {
      const helperId = helperText ? id + "-helper" : "";
      const errorId = id + "-error";
      const describedBy = [helperId, errorId].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <div class="field-meta">
            <label for="${id}">${label}</label>
            ${required ? '<span class="required-badge">Required</span>' : ""}
          </div>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            placeholder="${placeholder}"
            value="${escapeHtml(value)}"
            ${required ? "required" : ""}
            aria-invalid="${errorText ? "true" : "false"}"
            aria-describedby="${describedBy}"
          />
          ${helperText ? `<p class="helper-text" id="${helperId}">${helperText}</p>` : ""}
          <p class="error-text" id="${errorId}" aria-live="polite">${errorText}</p>
        </div>
      `;
    }

    function ContactForm() {
      return `
        <section class="form-panel" aria-labelledby="support-form-title">
          <div class="panel-heading">
            <h2 id="support-form-title">Send a support request</h2>
            <p>Share your details and our support team will follow up with the right next step.</p>
          </div>
          <form id="support-form" novalidate>
            ${Field({
              id: "fullName",
              label: "Full name",
              type: "text",
              placeholder: "Jordan Lee",
              value: fieldState.fullName,
              required: true,
              helperText: "",
              errorText: fieldErrors.fullName
            })}
            ${Field({
              id: "email",
              label: "Email address",
              type: "email",
              placeholder: "jordan@example.com",
              value: fieldState.email,
              required: true,
              helperText: "",
              errorText: fieldErrors.email
            })}
            ${Field({
              id: "phone",
              label: "Phone number",
              type: "tel",
              placeholder: "+1 (555) 123-4567",
              value: fieldState.phone,
              required: false,
              helperText: "Optional. Enter digits with spaces or symbols, for example +1 (555) 123-4567.",
              errorText: fieldErrors.phone
            })}
            <div class="submit-row">
              <button class="submit-button" type="submit">Submit request</button>
              <p class="status-message ${formStatusType}" aria-live="polite">${formStatus}</p>
            </div>
          </form>
        </section>
      `;
    }

    function SupportHero() {
      return `
        <section class="hero-panel" aria-labelledby="support-page-title">
          <div>
            <div class="eyebrow">Product Support</div>
            <h1 id="support-page-title">Get help from the team that builds the product.</h1>
            <p class="hero-copy">
              Reach out with account, billing, or setup questions and we will route your request to the right specialist.
            </p>
          </div>
          <div class="highlights" aria-label="Support highlights">
            <div class="highlight-card">
              <strong>Clear responses</strong>
              <span>Share the essentials once and avoid back-and-forth on basic details.</span>
            </div>
            <div class="highlight-card">
              <strong>Fast routing</strong>
              <span>Your request goes straight to the product support queue with contact information attached.</span>
            </div>
          </div>
        </section>
      `;
    }

    function SupportPage() {
      return `
        <main class="page-shell">
          ${SupportHero()}
          ${ContactForm()}
        </main>
      `;
    }

    function attachFormHandlers() {
      const form = document.getElementById("support-form");
      const fields = Array.from(form.querySelectorAll("input"));

      fields.forEach((field) => {
        field.addEventListener("input", (event) => {
          fieldState[event.target.name] = event.target.value;
          fieldErrors[event.target.name] = validateField(event.target.name, event.target.value);
          formStatus = "";
          formStatusType = "";
          renderApp();
        });

        field.addEventListener("blur", (event) => {
          fieldErrors[event.target.name] = validateField(event.target.name, event.target.value);
          renderApp();
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!validateForm()) {
          formStatus = "Please correct the highlighted fields.";
          formStatusType = "error";
          renderApp();
          const firstInvalidField = document.querySelector('input[aria-invalid="true"]');
          if (firstInvalidField) {
            firstInvalidField.focus();
          }
          return;
        }

        formStatus = "Thanks. Your support request is ready to send.";
        formStatusType = "success";
        renderApp();
      });
    }

    function renderApp() {
      document.getElementById("app").innerHTML = SupportPage();
      attachFormHandlers();
    }

    renderApp();
  </script>
</body>
</html>
