     function SupportHero() {
       return `
         <section class="hero-panel" aria-labelledby="support-page-title">
           <div>
             <div class="eyebrow">Product Support</div>
             <h1 id="support-page-title">Get help from the team that builds the product.</h1>
             <p class="hero-copy">
               Reach out with account, billing, or setup questions and we will route your request to the right specialist.
             </p>
           </div>
           <div class="highlights" aria-label="Support highlights">
             <div class="highlight-card">
               <strong>Clear responses</strong>
               <span>Share the essentials once and avoid back-and-forth on basic details.</span>
             </div>
             <div class="highlight-card">
               <strong>Fast routing</strong>
               <span>Your request goes straight to the product support queue with contact information attached.</span>
             </div>
           </div>
         </section>
       `;
     }

     function SupportPage() {
       return `
         <main class="page-shell">
           ${SupportHero()}
           ${ContactForm()}
         </main>
       `;
     }

     function updateUi() {
       Object.keys(fieldState).forEach((fieldName) => {
         const input = document.getElementById(fieldName);
         const error = document.getElementById(fieldName + "-error");

         if (input && input.value !== fieldState[fieldName]) {
           input.value = fieldState[fieldName];
         }

         if (input) {
           input.setAttribute("aria-invalid", fieldErrors[fieldName] ? "true" : "false");
         }

         if (error) {
           error.textContent = fieldErrors[fieldName];
         }
       });

       const status = document.querySelector(".status-message");
       if (status) {
         status.textContent = formStatus;
         status.className = "status-message" + (formStatusType ? " " + formStatusType : "");
       }
     }

     function attachFormHandlers() {
       const form = document.getElementById("support-form");
       const fields = Array.from(form.querySelectorAll("input"));

       fields.forEach((field) => {
         field.addEventListener("input", (event) => {
           const { name, value } = event.target;
           fieldState[name] = value;
           fieldErrors[name] = validateField(name, value);
           formStatus = "";
           formStatusType = "";
           updateUi();
         });

         field.addEventListener("blur", (event) => {
           const { name, value } = event.target;
           fieldState[name] = value;
           fieldErrors[name] = validateField(name, value);
           updateUi();
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         fields.forEach((field) => {
           fieldState[field.name] = field.value;
         });

         if (!validateForm()) {
           formStatus = "Please correct the highlighted fields.";
           formStatusType = "error";
           updateUi();
           const firstInvalidField = document.querySelector('input[aria-invalid="true"]');
           if (firstInvalidField) {
             firstInvalidField.focus();
           }
           return;
         }

         formStatus = "Thanks. Your support request is ready to send.";
         formStatusType = "success";
         updateUi();
       });
